/// <summary>In-memory <see cref="IInventoryStore"/>.</summary>
public sealed class InMemoryInventoryStore : IInventoryStore
{
    private readonly Dictionary<string, (int OnHand, int Reserved)> _data = new(StringComparer.Ordinal);

    public void Save(string sku, int onHand, int reserved) => _data[sku] = (onHand, reserved);

    public int? Load(string sku) => _data.TryGetValue(sku, out var v) ? v.OnHand : null;
